using TradeWorkflow.Application.Contracts;
using TradeWorkflow.Domain.Entities;

namespace TradeWorkflow.Infrastructure.Services;

public class ValidationService : IValidationService
{
    public Task<(bool IsValid, string? ErrorMessage)> ValidateTradeAsync(Trade trade)
    {
        var errors = new List<string>();

        if (string.IsNullOrWhiteSpace(trade.TradeReference))
            errors.Add("Trade reference is required");

        if (string.IsNullOrWhiteSpace(trade.Instrument))
            errors.Add("Instrument is required");

        if (string.IsNullOrWhiteSpace(trade.Counterparty))
            errors.Add("Counterparty is required");

        if (trade.Quantity <= 0)
            errors.Add("Quantity must be greater than zero");

        if (trade.Price <= 0)
            errors.Add("Price must be greater than zero");

        if (trade.TradeDate == default)
            errors.Add("Trade date is required");

        if (string.IsNullOrWhiteSpace(trade.TradeType))
            errors.Add("Trade type is required");

        var isValid = errors.Count == 0;
        var errorMessage = isValid ? null : string.Join("; ", errors);

        return Task.FromResult((isValid, errorMessage));
    }
}

