using FluentAssertions;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Moq;
using TradeWorkflow.API.Controllers;
using TradeWorkflow.API.Models;
using TradeWorkflow.Application.Services;
using TradeWorkflow.Domain.Entities;
using TradeWorkflow.Domain.Enums;
using TradeWorkflow.Tests.Builders;
using Xunit;

namespace TradeWorkflow.Tests.API;

public class TradesControllerTests
{
    private readonly Mock<TradeWorkflowService> _workflowServiceMock;
    private readonly Mock<ILogger<TradesController>> _loggerMock;
    private readonly TradesController _controller;

    public TradesControllerTests()
    {
        _workflowServiceMock = new Mock<TradeWorkflowService>(
            Mock.Of<Application.Contracts.ITradeRepository>(),
            Mock.Of<Application.Contracts.ITradeHistoryRepository>(),
            Mock.Of<Application.Contracts.IValidationService>(),
            Mock.Of<Application.Contracts.IDuplicateCheckService>(),
            Mock.Of<Application.Contracts.ITradeProcessingService>(),
            Mock.Of<ILogger<Application.StateMachine.TradeStateMachine>>());

        _loggerMock = new Mock<ILogger<TradesController>>();
        _controller = new TradesController(_workflowServiceMock.Object, _loggerMock.Object);
    }

    [Fact]
    public async Task CreateTrade_ShouldReturnCreatedResult()
    {
        // Arrange
        var request = new CreateTradeRequest
        {
            TradeReference = "TRD-001",
            Instrument = "AAPL",
            Quantity = 100,
            Price = 150.50m,
            Counterparty = "ABC Corp",
            TradeDate = DateTime.UtcNow,
            TradeType = "Buy"
        };

        var trade = TradeBuilder.Default().Build();
        _workflowServiceMock.Setup(x => x.CreateTradeAsync(It.IsAny<Trade>()))
            .ReturnsAsync(trade);
        _workflowServiceMock.Setup(x => x.GetPermittedTriggersAsync(trade.Id))
            .ReturnsAsync(new[] { TcrTrigger.StartValidation });

        // Act
        var result = await _controller.CreateTrade(request);

        // Assert
        result.Result.Should().BeOfType<CreatedAtActionResult>();
        var createdResult = result.Result as CreatedAtActionResult;
        createdResult!.Value.Should().BeOfType<TradeResponse>();
        var response = createdResult.Value as TradeResponse;
        response!.Id.Should().Be(trade.Id);
    }

    [Fact]
    public async Task GetTrade_WhenTradeExists_ShouldReturnOkResult()
    {
        // Arrange
        var trade = TradeBuilder.Default().Build();
        _workflowServiceMock.Setup(x => x.GetTradeAsync(trade.Id))
            .ReturnsAsync(trade);
        _workflowServiceMock.Setup(x => x.GetPermittedTriggersAsync(trade.Id))
            .ReturnsAsync(new[] { TcrTrigger.StartValidation });

        // Act
        var result = await _controller.GetTrade(trade.Id);

        // Assert
        result.Result.Should().BeOfType<OkObjectResult>();
        var okResult = result.Result as OkObjectResult;
        okResult!.Value.Should().BeOfType<TradeResponse>();
    }

    [Fact]
    public async Task GetTrade_WhenTradeDoesNotExist_ShouldReturnNotFound()
    {
        // Arrange
        var tradeId = Guid.NewGuid();
        _workflowServiceMock.Setup(x => x.GetTradeAsync(tradeId))
            .ReturnsAsync((Trade?)null);

        // Act
        var result = await _controller.GetTrade(tradeId);

        // Assert
        result.Result.Should().BeOfType<NotFoundObjectResult>();
    }

    [Fact]
    public async Task GetAllTrades_ShouldReturnOkResultWithTrades()
    {
        // Arrange
        var trades = new List<Trade>
        {
            TradeBuilder.Default().WithId(Guid.NewGuid()).Build(),
            TradeBuilder.Default().WithId(Guid.NewGuid()).Build()
        };

        _workflowServiceMock.Setup(x => x.GetAllTradesAsync())
            .ReturnsAsync(trades);

        foreach (var trade in trades)
        {
            _workflowServiceMock.Setup(x => x.GetPermittedTriggersAsync(trade.Id))
                .ReturnsAsync(new[] { TcrTrigger.StartValidation });
        }

        // Act
        var result = await _controller.GetAllTrades();

        // Assert
        result.Result.Should().BeOfType<OkObjectResult>();
        var okResult = result.Result as OkObjectResult;
        var responseList = okResult!.Value as List<TradeResponse>;
        responseList.Should().HaveCount(2);
    }

    [Fact]
    public async Task ProcessTrigger_WhenValid_ShouldReturnOkResult()
    {
        // Arrange
        var trade = TradeBuilder.Default()
            .WithState(TcrState.Received)
            .Build();

        var request = new ProcessTriggerRequest
        {
            Trigger = TcrTrigger.StartValidation
        };

        _workflowServiceMock.Setup(x => x.ProcessTriggerAsync(trade.Id, TcrTrigger.StartValidation))
            .ReturnsAsync(TcrState.ValidationInProgress);
        _workflowServiceMock.Setup(x => x.GetTradeAsync(trade.Id))
            .ReturnsAsync(trade);
        _workflowServiceMock.Setup(x => x.GetPermittedTriggersAsync(trade.Id))
            .ReturnsAsync(Array.Empty<TcrTrigger>());

        // Act
        var result = await _controller.ProcessTrigger(trade.Id, request);

        // Assert
        result.Result.Should().BeOfType<OkObjectResult>();
    }

    [Fact]
    public async Task ProcessTrigger_WhenInvalid_ShouldReturnBadRequest()
    {
        // Arrange
        var tradeId = Guid.NewGuid();
        var request = new ProcessTriggerRequest
        {
            Trigger = TcrTrigger.CreateNew
        };

        _workflowServiceMock.Setup(x => x.ProcessTriggerAsync(tradeId, TcrTrigger.CreateNew))
            .ThrowsAsync(new InvalidOperationException("Cannot fire trigger"));

        // Act
        var result = await _controller.ProcessTrigger(tradeId, request);

        // Assert
        result.Result.Should().BeOfType<BadRequestObjectResult>();
    }

    [Fact]
    public async Task GetPermittedTriggers_WhenTradeExists_ShouldReturnTriggers()
    {
        // Arrange
        var tradeId = Guid.NewGuid();
        var triggers = new[] { TcrTrigger.StartValidation };

        _workflowServiceMock.Setup(x => x.GetPermittedTriggersAsync(tradeId))
            .ReturnsAsync(triggers);

        // Act
        var result = await _controller.GetPermittedTriggers(tradeId);

        // Assert
        result.Result.Should().BeOfType<OkObjectResult>();
        var okResult = result.Result as OkObjectResult;
        var triggerStrings = okResult!.Value as IEnumerable<string>;
        triggerStrings.Should().Contain("StartValidation");
    }

    [Fact]
    public async Task GetPermittedTriggers_WhenTradeDoesNotExist_ShouldReturnNotFound()
    {
        // Arrange
        var tradeId = Guid.NewGuid();
        _workflowServiceMock.Setup(x => x.GetPermittedTriggersAsync(tradeId))
            .ThrowsAsync(new InvalidOperationException($"Trade with ID {tradeId} not found"));

        // Act
        var result = await _controller.GetPermittedTriggers(tradeId);

        // Assert
        result.Result.Should().BeOfType<NotFoundObjectResult>();
    }

    [Fact]
    public async Task GetTradeHistory_ShouldReturnHistory()
    {
        // Arrange
        var tradeId = Guid.NewGuid();
        var history = new List<TradeHistory>
        {
            new TradeHistory
            {
                Id = Guid.NewGuid(),
                TradeId = tradeId,
                FromState = TcrState.Received,
                ToState = TcrState.ValidationInProgress,
                Trigger = TcrTrigger.StartValidation,
                TransitionedAt = DateTime.UtcNow
            }
        };

        _workflowServiceMock.Setup(x => x.GetTradeHistoryAsync(tradeId))
            .ReturnsAsync(history);

        // Act
        var result = await _controller.GetTradeHistory(tradeId);

        // Assert
        result.Result.Should().BeOfType<OkObjectResult>();
        var okResult = result.Result as OkObjectResult;
        var historyList = okResult!.Value as IEnumerable<TradeHistoryResponse>;
        historyList.Should().HaveCount(1);
    }
}

